$ErrorActionPreference='Stop'
Import-Module WebAdministration
$site='EharmonyWechatTest-Isolated'
$pool='EharmonyAndroidDownloadTest-Isolated'
$app='android-download-test'
$root='C:\Sites\eharmony-wechat-test\android-download-test'
$parent=Get-Website -Name $site -ErrorAction Stop
if($parent.PhysicalPath -ne 'C:\Sites\eharmony-wechat-test\www'){throw 'Unexpected test site path; stopped.'}
function Snapshot-OtherSites {
 $rows=@(Get-Website|Where-Object Name -ne $site|Sort-Object Name|ForEach-Object {[pscustomobject]@{name=$_.Name;state=[string]$_.State;path=$_.PhysicalPath;bindings=@($_.Bindings.Collection|ForEach-Object {$_.protocol+' '+$_.bindingInformation+' '+$_.sslFlags}|Sort-Object)}})
 ConvertTo-Json -InputObject $rows -Depth 8 -Compress
}
$before=Snapshot-OtherSites
$existing=Get-WebApplication -Site $site -Name $app -ErrorAction SilentlyContinue
if($existing -and $existing.PhysicalPath -ne $root){throw 'Application path is occupied; stopped.'}
if((Test-Path "IIS:\AppPools\$pool") -and !$existing){throw 'Pool name already exists; stopped.'}
New-Item -ItemType Directory -Path $root -Force|Out-Null
$backup=Join-Path 'C:\Sites\eharmony-wechat-test\backups' ('android-'+(Get-Date -Format yyyyMMdd-HHmmss))
New-Item -ItemType Directory -Path $backup -Force|Out-Null
$payload=ConvertFrom-Json @'
{"index.html":"","probe.ashx":"","test.xlsx":"","web.config":""}
'@
foreach($p in $payload.PSObject.Properties){
 $destination=Join-Path $root $p.Name
 if(Test-Path -LiteralPath $destination){Copy-Item -LiteralPath $destination -Destination (Join-Path $backup $p.Name)}
 [IO.File]::WriteAllBytes($destination,[Convert]::FromBase64String($p.Value))
}
if(!(Test-Path "IIS:\AppPools\$pool")){New-WebAppPool -Name $pool|Out-Null}
Set-ItemProperty "IIS:\AppPools\$pool" -Name managedRuntimeVersion -Value 'v4.0'
if(!$existing){New-WebApplication -Site $site -Name $app -PhysicalPath $root -ApplicationPool $pool|Out-Null}
& icacls.exe $root /grant ("IIS AppPool\"+$pool+':(OI)(CI)(RX)') /T /C|Out-Null
if($LASTEXITCODE -ne 0){throw 'Read permissions failed.'}
if((Get-WebAppPoolState -Name $pool).Value -ne 'Started'){Start-WebAppPool $pool}
$base='http://127.0.0.1/android-download-test/'
$headers=@{Host='eharmony.me'}
$entry=Invoke-WebRequest -UseBasicParsing ($base+'index.html') -Headers $headers -TimeoutSec 20
if($entry.StatusCode -ne 200){throw 'Entry check failed'}
$ua='Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 MicroMessenger/8.0.50'
$download=Invoke-WebRequest -UseBasicParsing ($base+'probe.ashx?type=xlsx') -Headers $headers -UserAgent $ua -TimeoutSec 20
if($download.Headers['Content-Disposition'] -notmatch 'browser-test.xlsx'){throw 'Attachment check failed'}
$browser=Invoke-WebRequest -UseBasicParsing ($base+'probe.ashx?type=xlsx') -Headers $headers -UserAgent 'Mozilla/5.0 Android Chrome/130' -TimeoutSec 20
if($browser.Headers['Content-Type'] -notmatch 'text/html'){throw 'Browser result check failed'}
if((Snapshot-OtherSites) -ne $before){throw 'Other site snapshot changed; inspect before continuing.'}
Write-Host 'READY: https://eharmony.me/android-download-test/' -ForegroundColor Green
Write-Host 'Other site paths, bindings and states are unchanged.' -ForegroundColor Green
